import React from 'react';
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ComposedChart, Area } from 'recharts';

const ComplaintTrackingChart = ({ analyzedData }) => {
  // Cyberpunk color palette with green and black focus
  const colors = {
    neon: {
      green: '#00ff41',      // Matrix green
      brightGreen: '#39ff14', // Bright lime green
      darkGreen: '#008f11',  // Dark matrix green
      accent: '#0abdc6',     // Subtle cyan accent
      yellow: '#caff70'      // Subtle yellow highlight
    },
    dark: {
      base: '#0d0208',       // Almost black
      secondary: '#0f100f',  // Very dark gray
      accent: '#121212'      // Dark charcoal
    },
    text: {
      primary: '#00ff41',    // Matrix green
      secondary: '#465b49'   // Muted green
    }
  };
  
  // Exit early if no data
  if (!analyzedData || !analyzedData.chunks || analyzedData.chunks.length === 0) {
    return (
      <div className="flex flex-col items-center w-full max-w-full mx-auto p-3 rounded-lg shadow-2xl border border-green-500" style={{
        background: `linear-gradient(135deg, ${colors.dark.base} 0%, ${colors.dark.secondary} 100%)`,
        boxShadow: `0 0 15px ${colors.neon.darkGreen}`
      }}>
        <h2 className="text-xl font-bold mb-2 font-mono uppercase tracking-widest" style={{color: colors.neon.green}}>TERMINAL // NO DATA AVAILABLE</h2>
      </div>
    );
  }
  
  // Process the chunks data for the chart
  const data = analyzedData.chunks.map((chunk, index) => {
    // Extract start and end time
    let timeRange = `Chunk ${index + 1}`;
    if (chunk.timestamp) {
      const timestamp = new Date(chunk.timestamp);
      timeRange = timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }
    
    // Calculate complaint level (0, 1, or 2 based on confidence)
    let complaintLevel = 0;
    if (chunk.isComplaint) {
      complaintLevel = chunk.confidence > 0.75 ? 2 : 1;
    }
    
    // Extract the first few words from the first utterance for description
    // More robust version with additional checks
    let description = '';
    try {
      // Check if chunk has text first as a fallback
      if (chunk.text) {
        // Use chunk text directly if available
        description = chunk.text.split(' ').slice(0, 5).join(' ');
        if (chunk.text.split(' ').length > 5) {
          description += '...';
        }
      } 
      // Otherwise try to get it from utterances
      else if (chunk.utterances && Array.isArray(chunk.utterances) && chunk.utterances.length > 0) {
        const utterance = chunk.utterances[0];
        
        // Check if the utterance has a text property
        if (utterance && typeof utterance.text === 'string') {
          description = utterance.text.split(' ').slice(0, 5).join(' ');
          if (utterance.text.split(' ').length > 5) {
            description += '...';
          }
        }
        // Check if the utterance itself is a string
        else if (utterance && typeof utterance === 'string') {
          description = utterance.split(' ').slice(0, 5).join(' ');
          if (utterance.split(' ').length > 5) {
            description += '...';
          }
        }
      }
      
      // If still empty, provide a default
      if (!description) {
        description = `Data Point ${index + 1}`;
      }
    } catch (error) {
      // Fallback for any unexpected errors
      console.error('Error processing description:', error);
      description = `Chunk ${index + 1}`;
    }
    
    return {
      window: `Window ${index + 1}`,
      timeRange,
      complaintLevel,
      complaintPercentage: Math.round(chunk.confidence * 100),
      description
    };
  });
  
  // Calculate the average complaint percentage
  const totalPercentage = data.reduce((sum, item) => sum + item.complaintPercentage, 0);
  const averagePercentage = (totalPercentage / data.length).toFixed(1);
  
  // Find the peak window (highest complaint percentage)
  const peakWindow = [...data].sort((a, b) => b.complaintPercentage - a.complaintPercentage)[0]?.window || 'NONE';
  
  // Calculate runtime from first to last chunk timestamp if available
  let runtime = 'N/A';
  if (analyzedData.chunks.length > 1 && analyzedData.chunks[0].timestamp && analyzedData.chunks[analyzedData.chunks.length - 1].timestamp) {
    const firstTime = new Date(analyzedData.chunks[0].timestamp).getTime();
    const lastTime = new Date(analyzedData.chunks[analyzedData.chunks.length - 1].timestamp).getTime();
    const diffSeconds = Math.floor((lastTime - firstTime) / 1000);
    const minutes = Math.floor(diffSeconds / 60);
    const seconds = diffSeconds % 60;
    runtime = `${minutes}M:${seconds}S`;
  }

  return (
    <div className="flex flex-col items-center w-full mx-auto mb-4 rounded-lg shadow-2xl border border-green-500" style={{
      background: `linear-gradient(135deg, ${colors.dark.base} 0%, ${colors.dark.secondary} 100%)`,
      boxShadow: `0 0 15px ${colors.neon.darkGreen}`
    }}>
      <h2 className="text-xl font-bold my-2 font-mono uppercase tracking-widest" style={{color: colors.neon.green}}>TERMINAL // CUSTOMER COMPLAINT MATRIX</h2>
      
      <div style={{ display: 'flex', width: '100%', flexWrap: 'wrap' }}>
        {/* Chart section - takes 70% on larger screens, 100% on mobile */}
        <div style={{ flex: '1 1 70%', minWidth: '300px' }} className="border border-green-400 rounded-lg m-2" style={{
          background: 'rgba(0, 20, 0, 0.7)', 
          boxShadow: `0 0 10px ${colors.neon.darkGreen}`
        }}>
          <ResponsiveContainer width="100%" height={300}>
            <ComposedChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 50 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,255,65,0.1)" />
              <XAxis 
                dataKey="window" 
                angle={-45} 
                textAnchor="end" 
                height={60} 
                tick={{ fontSize: 10, fill: colors.text.primary, fontFamily: 'monospace' }}
                stroke={colors.text.secondary}
              />
              <YAxis 
                yAxisId="left" 
                label={{ value: 'LEVEL', angle: -90, position: 'insideLeft', fill: colors.neon.green, fontSize: 10, fontFamily: 'monospace' }} 
                tick={{ fill: colors.text.primary, fontFamily: 'monospace', fontSize: 10 }}
                stroke={colors.text.secondary}
              />
              <YAxis 
                yAxisId="right" 
                orientation="right" 
                label={{ value: '%', angle: 90, position: 'insideRight', fill: colors.neon.green, fontSize: 10, fontFamily: 'monospace' }} 
                tick={{ fill: colors.text.primary, fontFamily: 'monospace', fontSize: 10 }}
                stroke={colors.text.secondary}
              />
              <Tooltip
                contentStyle={{ 
                  backgroundColor: 'rgba(0, 20, 0, 0.9)', 
                  borderColor: colors.neon.green,
                  color: colors.neon.green,
                  boxShadow: `0 0 10px ${colors.neon.green}`,
                  borderRadius: '0px',
                  fontFamily: 'monospace'
                }}
                formatter={(value, name) => {
                  if (name === "complaintLevel") {
                    const levels = ["None", "Mild", "Strong"];
                    return [levels[value], "LEVEL"];
                  }
                  return [value + "%", "RATIO"];
                }}
                labelFormatter={(value, items) => {
                  const item = data.find(d => d.window === value);
                  return `${value} (${item.timeRange})`;
                }}
              />
              <Legend 
                wrapperStyle={{
                  color: colors.neon.green,
                  fontFamily: 'monospace',
                  fontSize: 10
                }}
              />
              <Bar 
                yAxisId="left"
                dataKey="complaintLevel" 
                fill={colors.neon.darkGreen}
                name="Complaint Level"
                barSize={20}
                animationDuration={1500}
                style={{filter: `drop-shadow(0 0 5px ${colors.neon.darkGreen})`}}
              />
              <Line 
                yAxisId="right"
                type="monotone" 
                dataKey="complaintPercentage" 
                stroke={colors.neon.green}
                name="Complaint %"
                strokeWidth={2}
                dot={{ fill: colors.neon.green, r: 3, strokeWidth: 0 }}
                activeDot={{ fill: colors.neon.brightGreen, r: 5, strokeWidth: 0 }}
                animationDuration={1500}
                style={{filter: `drop-shadow(0 0 5px ${colors.neon.green})`}}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
        
        {/* System diagnostics and data table - takes 30% on larger screens, 100% on mobile */}
        <div style={{ flex: '1 1 30%', minWidth: '300px' }} className="m-2">
          {/* System diagnostics panel */}
          <div className="bg-gray-900 p-3 rounded-lg shadow-lg mb-3 border border-green-500" style={{
            background: 'rgba(0, 20, 0, 0.7)', 
            boxShadow: `0 0 10px ${colors.neon.darkGreen}`
          }}>
            <h3 className="text-sm font-mono font-semibold mb-2 text-center uppercase tracking-wider" style={{color: colors.neon.green}}>// SYSTEM DIAGNOSTICS //</h3>
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 5px ${colors.neon.darkGreen}`}}>
                <span className="text-xs font-mono text-gray-400 uppercase">RATIO</span>
                <span className="text-lg font-bold font-mono" style={{color: colors.neon.green}}>{averagePercentage}%</span>
              </div>
              <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 5px ${colors.neon.darkGreen}`}}>
                <span className="text-xs font-mono text-gray-400 uppercase">PEAK</span>
                <span className="text-lg font-bold font-mono" style={{color: colors.neon.green}}>{peakWindow.split(' ')[1]}</span>
              </div>
              <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 5px ${colors.neon.darkGreen}`}}>
                <span className="text-xs font-mono text-gray-400 uppercase">TIME</span>
                <span className="text-lg font-bold font-mono" style={{color: colors.neon.green}}>{runtime}</span>
              </div>
            </div>
          </div>
          
          {/* Conversation data table - condensed for better fit */}
          <div style={{maxHeight: '160px', overflow: 'auto', boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <table className="min-w-full bg-black border border-green-500" style={{fontSize: '10px'}}>
              <thead>
                <tr className="bg-gray-900 border-b border-green-500">
                  <th className="p-1 border-r border-green-500 font-mono text-xs" style={{color: colors.neon.green}}>SEQ</th>
                  <th className="p-1 border-r border-green-500 font-mono text-xs" style={{color: colors.neon.green}}>STATUS</th>
                  <th className="p-1 font-mono text-xs" style={{color: colors.neon.green}}>DATA</th>
                </tr>
              </thead>
              <tbody style={{fontFamily: 'monospace'}}>
                {data.map((item, index) => (
                  <tr key={index} className={`border-b border-green-900 ${index % 2 === 0 ? 'bg-black' : 'bg-gray-900'}`}>
                    <td className="p-1 border-r border-green-900 font-mono font-medium text-xs" style={{color: colors.neon.green}}>{index + 1}</td>
                    <td className="p-1 border-r border-green-900">
                      <span className={`px-1 py-0 text-xs font-semibold font-mono
                        ${item.complaintLevel === 0 ? 'bg-black text-green-400 border border-green-500' : 
                          item.complaintLevel === 1 ? 'bg-black text-yellow-400 border border-yellow-500' : 
                          'bg-black text-red-400 border border-red-500'}`}
                        style={{
                          boxShadow: item.complaintLevel === 0 ? `0 0 3px ${colors.neon.green}` : 
                                    item.complaintLevel === 1 ? `0 0 3px ${colors.neon.yellow}` : 
                                    `0 0 3px red`
                        }}>
                        {item.complaintLevel === 0 ? 'OK' : 
                         item.complaintLevel === 1 ? 'WARN' : 'ALRT'}
                      </span>
                    </td>
                    <td className="p-1 font-mono text-xs" style={{color: colors.neon.darkGreen, maxWidth: '150px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis'}}>{item.description}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
      
      <div className="w-full text-center mt-1 mb-1 font-mono text-xs" style={{color: colors.neon.darkGreen}}>
        <p>CORP//MAINFRAME [v3.5.2] © 2025 | SESSION: XR-{Math.floor(Math.random() * 10000)} | TERMINAL: ACTIVE</p>
      </div>
    </div>
  );
};

export default ComplaintTrackingChart;
